components.css:
.theme-picker{position:relative;min-height:242px;width:224px;--font:"Hanken Grotesk",sans-serif;--display:"EB Garamond",serif;--text:#102d3b;--text-2:#486170;--text-3:#526c79;--paper:#f5f8f7;--ink:#102d3b;--surface:#e8f0f1;--accent:#286078;--line:#cedbdf;--line-strong:#9bb0ba;}
.visually-hidden { position: absolute !important; width: 1px !important; height: 1px !important; padding: 0 !important; margin: -1px !important; overflow: hidden !important; clip-path: inset(50%) !important; white-space: nowrap !important; border: 0 !important; }
.theme-picker { position: relative; z-index: 2; flex: 0 0 auto; color: var(--paper); font: 500 14px/1.2 var(--font); }
.theme-picker__trigger { display: flex; align-items: center; justify-content: flex-end; gap: 9px; min-height: 44px; min-width: 78px; padding: 0 4px; }
.theme-picker__trigger:hover, .theme-picker__trigger[aria-expanded="true"] { color: var(--signal); }
.theme-picker__trigger svg { flex: 0 0 auto; transition: transform var(--t) var(--ease); }
.theme-picker__trigger[aria-expanded="true"] svg { transform: rotate(180deg); }
.theme-picker__options { position: absolute; top: calc(100% + 10px); right: 0; width: 224px; max-width: calc(100vw - 32px); min-width: 0; margin: 0; padding: 8px; color: var(--ink); background: var(--paper); border: 1px solid var(--line); animation: appearance-open 160ms var(--ease); }
.theme-picker__options label { display: block; position: relative; cursor: pointer; }
.theme-picker__options label > span { display: flex; align-items: center; gap: 12px; min-height: 56px; padding: 8px 12px; }
.theme-picker__label { flex: 1; }
.theme-picker__swatch { display: block; position: relative; flex: 0 0 30px; height: 30px; border: 1px solid #9bb0ba; background: #f2f6f5; overflow: hidden; }
.theme-picker__swatch::after { content: ""; position: absolute; inset: 0 0 0 55%; background: #9bb0ba; }
.theme-picker__swatch--black { background: #0b141b; }
.theme-picker__swatch--black::after { background: #5d7684; }
.theme-picker__swatch--dark { background: #101010; }
.theme-picker__swatch--dark::after { background: #ff1735; }
.theme-picker__options svg { opacity: 0; }
.theme-picker__options input:checked + span { color: var(--paper); background: var(--ink); }
.theme-picker__options input:checked + span svg { opacity: 1; }
.theme-picker__options label:hover > span { color: var(--ink); background: var(--signal); }
.theme-picker__options input:focus-visible + span { outline: 2px solid currentColor; outline-offset: -2px; }
.theme-picker { color: var(--text-3); margin-left: 0; }
.theme-picker__trigger { justify-content: center; width: 44px; min-width: 44px; min-height: 44px; padding: 10px; color: var(--text-2); }
.theme-picker__trigger [data-theme-name], .theme-picker__trigger > svg:not(.ink-appearance-icon) { display: none; }
.theme-picker__trigger .ink-appearance-icon { display: block; flex: none; width: 20px; height: 20px; transform: none; }
.theme-picker__trigger:hover, .theme-picker__trigger[aria-expanded="true"] { color: var(--accent); background: var(--surface); }
.theme-picker__options { padding: 8px; width: 224px; box-shadow: 0 12px 28px rgb(23 53 66 / .12); }
.theme-picker__options label > span { min-height: 56px; font: 400 21px/1.3 var(--display); }
.theme-picker__options { color: var(--text); background: var(--paper); border-color: var(--line-strong); }
.theme-picker__options input:checked + span, .theme-picker__options label:hover > span { color: var(--ink); background: var(--surface); }

/* Three illustrated scenes with numbered steps in live HTML below the artwork. */
.ds-research-feature { display:block; padding-block:48px 56px; }
.ds-research-feature__text { display:block; }
.ds-research-feature h2 { margin:0 0 16px; }
.ds-research-feature__text > p { max-width:76ch; margin:0 0 28px; }
.ds-research-feature__figure { margin:0; }
.ds-research-feature figcaption { display:block; margin:20px 0 0; }
.ds-research-feature figcaption > span { color:var(--text-2); font:italic 23px/1.45 var(--display); }
.ds-research-feature__sources { display:flex; flex-wrap:wrap; align-items:center; gap:8px 28px; margin:12px 0 0; color:var(--text-2); font-size:14px; }
.ds-research-feature__sources > span { margin-right:auto; }
.ds-research-feature__sources a { display:inline-flex; align-items:center; min-height:44px; color:var(--accent); text-underline-offset:5px; }
.ds-research-diagram { max-width:1040px; margin-inline:auto; padding:0 0 20px; }
.ds-diagram-heading { display:flex; justify-content:flex-end; }
.ds-diagram-heading h3 { position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
.ds-diagram-play { min-height:44px; min-width:64px; padding:8px; border:0; border-bottom:1px solid var(--line-strong); background:transparent; color:var(--text-2); font:inherit; font-size:14px; cursor:pointer; }
.ds-diagram-play:hover { color:var(--accent); border-color:var(--accent); }
.ds-diagram-art { margin:0 auto 28px; }
.ds-research-scene-svg { display:block; width:100%; height:auto; overflow:visible; stroke-linecap:round; stroke-linejoin:round; }
.ds-scene-steps { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px 40px; margin:12px 0 0; padding:0; list-style:none; }
.ds-explain-step { display:grid; grid-template-columns:28px minmax(0,1fr); gap:0 12px; min-width:0; margin:0; padding-top:16px; border-top:1px solid var(--line); transition:border-color .3s; }
.ds-explain-step[data-active="true"] { border-top-color:var(--accent); }
.ds-scene-step__n { display:grid; place-items:center; width:26px; height:26px; margin-top:1px; border:1px solid var(--line-strong); border-radius:50%; color:var(--text-2); font-size:13px; font-variant-numeric:tabular-nums; transition:background-color .3s, color .3s, border-color .3s; }
.ds-explain-step[data-active="true"] .ds-scene-step__n { border-color:var(--accent); background:var(--accent); color:var(--bg); }
.ds-explain-step h4 { margin:0 0 8px; color:var(--text); font:400 23px/1.2 var(--display); }
.ds-explain-step p { max-width:36ch; margin:0; color:var(--text-2); font-size:15px; line-height:1.6; }

/* Scene palette. Light: pale paper objects inked in navy-steel, with brass and a restrained teal. */
