  --sc-s0:#e5eff3; --sc-s1:#d3e4eb; --sc-s2:#c0d6e0; --sc-s3:#abc7d4; --sc-s4:#97b8c9;
  --sc-b0:#fbf2dc; --sc-b1:#f2e1ba; --sc-b2:#e7cd97; --sc-b3:#d9b776; --sc-b4:#c7a05a;
  --sc-k0:#304b5a; --sc-k1:#253f4e; --sc-k2:#1d3544; --sc-k3:#172d3b; --sc-k4:#112532;
  --sc-edge:#56717f; --sc-edge-b:#a07c3c; --sc-edge-k:#0f2a38; --sc-fine:#91a7b2; --sc-grid:#dce6e9;
  --sc-ink:#102d3b; --sc-accent:#286078; --sc-soft:#bcd7e3; --sc-glow:#3d95bb; --sc-warm:#c48a2a; --sc-ok:#2b8a74; --sc-wait:#d29a35;
  --sc-screen:#163240; --sc-screen-ink:#8cc2d6; --sc-screen-hi:#d8f0f8; --sc-shadow:#1b3a4b; --sc-bg:var(--bg);
  --sc-w:.85px; --sc-w-fine:.6px; --mk:1;
}
:root[data-theme="black"] .ds-research-diagram {
  --sc-w0:#253c4b; --sc-w1:#1e3443; --sc-w2:#1a2e3b; --sc-w3:#162834; --sc-w4:#12222c;
  --sc-s0:#284a5d; --sc-s1:#224254; --sc-s2:#1d3a4a; --sc-s3:#193341; --sc-s4:#152c38;
  --sc-b0:#6d5832; --sc-b1:#5e4c2b; --sc-b2:#514126; --sc-b3:#443720; --sc-b4:#382e1b;
  --sc-k0:#0f1b23; --sc-k1:#0d171e; --sc-k2:#0b141a; --sc-k3:#091116; --sc-k4:#070e12;
  --sc-edge:#88a8b7; --sc-edge-b:#d3af6d; --sc-edge-k:#5f7f8e; --sc-fine:#58778a; --sc-grid:#1b2c37;
  --sc-ink:#e5eceb; --sc-accent:#a9cbd9; --sc-soft:#3f6476; --sc-glow:#8ccfe8; --sc-warm:#e6ba68; --sc-ok:#72d1b8; --sc-wait:#e8b45c;
  --sc-screen:#071219; --sc-screen-ink:#78b4ca; --sc-screen-hi:#d8f2fb; --sc-shadow:#000;
}
:root[data-theme="dark"] .ds-research-diagram {
  --sc-w0:#2f2f2f; --sc-w1:#282828; --sc-w2:#232323; --sc-w3:#1e1e1e; --sc-w4:#1a1a1a;
  --sc-s0:#3b2b2f; --sc-s1:#34262a; --sc-s2:#2e2125; --sc-s3:#281d20; --sc-s4:#22191c;
  --sc-b0:#54493a; --sc-b1:#4a4033; --sc-b2:#40382d; --sc-b3:#373026; --sc-b4:#2e2820;
  --sc-k0:#121212; --sc-k1:#101010; --sc-k2:#0e0e0e; --sc-k3:#0c0c0c; --sc-k4:#0a0a0a;
  --sc-edge:#c8c8c3; --sc-edge-b:#e2c68f; --sc-edge-k:#8e8e8a; --sc-fine:#6f6f6c; --sc-grid:#262626;
  --sc-ink:#fafaf7; --sc-accent:#ff7189; --sc-soft:#6a3540; --sc-glow:#ff8fa2; --sc-warm:#ffc66e; --sc-ok:#92e2c9; --sc-wait:#ffc66e;
  --sc-screen:#0b0b0b; --sc-screen-ink:#ff9cae; --sc-screen-hi:#ffe2e8; --sc-shadow:#000;
}
.ds-research-scene-svg .ds-w0 { fill:var(--sc-w0); } .ds-research-scene-svg .ds-w1 { fill:var(--sc-w1); } .ds-research-scene-svg .ds-w2 { fill:var(--sc-w2); } .ds-research-scene-svg .ds-w3 { fill:var(--sc-w3); } .ds-research-scene-svg .ds-w4 { fill:var(--sc-w4); }
.ds-research-scene-svg .ds-s0 { fill:var(--sc-s0); } .ds-research-scene-svg .ds-s1 { fill:var(--sc-s1); } .ds-research-scene-svg .ds-s2 { fill:var(--sc-s2); } .ds-research-scene-svg .ds-s3 { fill:var(--sc-s3); } .ds-research-scene-svg .ds-s4 { fill:var(--sc-s4); }
.ds-research-scene-svg .ds-b0 { fill:var(--sc-b0); } .ds-research-scene-svg .ds-b1 { fill:var(--sc-b1); } .ds-research-scene-svg .ds-b2 { fill:var(--sc-b2); } .ds-research-scene-svg .ds-b3 { fill:var(--sc-b3); } .ds-research-scene-svg .ds-b4 { fill:var(--sc-b4); }
.ds-research-scene-svg .ds-k0 { fill:var(--sc-k0); } .ds-research-scene-svg .ds-k1 { fill:var(--sc-k1); } .ds-research-scene-svg .ds-k2 { fill:var(--sc-k2); } .ds-research-scene-svg .ds-k3 { fill:var(--sc-k3); } .ds-research-scene-svg .ds-k4 { fill:var(--sc-k4); }
.ds-research-scene-svg :is(.ds-e,.ds-eb,.ds-ek,.ds-e-s,.ds-dt,.ds-grid,.ds-chev,.ds-hid,.ds-lead,.ds-sl,.ds-pic,.ds-patch-e,.ds-ripple) { vector-effect:non-scaling-stroke; }
.ds-research-scene-svg .ds-e, .ds-research-scene-svg .ds-e-s { fill:none; stroke:var(--sc-edge); stroke-width:var(--sc-w); }
.ds-research-scene-svg .ds-eb { fill:none; stroke:var(--sc-edge-b); stroke-width:var(--sc-w); }
