.ds-research-scene-svg .ds-sl { fill:none; stroke:var(--sc-screen-ink); stroke-width:var(--sc-w-fine); }
.ds-research-scene-svg .ds-sl-fill, .ds-research-scene-svg .ds-dotp { fill:var(--sc-screen-hi); }
.ds-research-scene-svg .ds-trace { fill:none; stroke:var(--sc-screen-hi); stroke-width:1.4; }
.ds-research-scene-svg .ds-eye { fill:var(--sc-glow); }
.ds-research-scene-svg .ds-pic { fill:none; stroke:var(--sc-accent); stroke-width:var(--sc-w); }
.ds-research-scene-svg .ds-cord { fill:none; stroke:var(--sc-edge); stroke-width:2.4; }
.ds-research-scene-svg .ds-cable { fill:none; stroke:var(--sc-ok); stroke-width:3.4; }
.ds-research-scene-svg .ds-cable-hi { fill:none; stroke:var(--sc-w0); stroke-width:1; opacity:.55; }
.ds-research-scene-svg .ds-beam { fill:var(--sc-glow); }
.ds-research-scene-svg .ds-scan { fill:none; stroke:var(--sc-glow); stroke-width:1.6; }
.ds-research-scene-svg .ds-lamp-wait { fill:var(--sc-wait); }
.ds-research-scene-svg .ds-lamp-ok { fill:var(--sc-ok); }
.ds-research-scene-svg .ds-tick { fill:none; stroke:var(--sc-ok); stroke-width:2.2; }
.ds-research-scene-svg .ds-cell0 { fill:var(--sc-w0); stroke:var(--sc-fine); stroke-width:.5; }
.ds-research-scene-svg .ds-cell1 { fill:var(--sc-soft); } .ds-research-scene-svg .ds-cell2 { fill:var(--sc-glow); } .ds-research-scene-svg .ds-cell3 { fill:var(--sc-accent); }
.ds-research-scene-svg .ds-scanbar { fill:none; stroke:var(--sc-glow); stroke-width:3; }
.ds-research-scene-svg .ds-groove { fill:none; stroke:var(--sc-w4); stroke-width:3.4; }
