.ds-research-scene-svg .ds-leak { fill:none; stroke:var(--sc-edge); stroke-width:1.3; }
.ds-research-scene-svg .ds-plan.thin { stroke-width:1.1; }
.ds-research-scene-svg .ds-well { fill:var(--sc-w3); stroke:var(--sc-edge); stroke-width:.7; }
.ds-research-scene-svg .ds-well-in { fill:var(--sc-w4); }
.ds-research-scene-svg .ds-bead { fill:var(--sc-glow); stroke:var(--sc-w0); stroke-width:.8; }
.ds-research-scene-svg .ds-bead.warm { fill:var(--sc-warm); }
