.ds-research-scene-svg .ds-mv { transition:transform .1s linear; }
.ds-diagram-controls { display:grid; grid-template-columns:auto minmax(100px,200px) minmax(150px,240px); justify-content:center; align-items:center; gap:12px 24px; color:var(--text-2); font-size:14px; }
.ds-diagram-controls input { width:100%; min-height:44px; margin:0; accent-color:var(--accent); cursor:ew-resize; }
.ds-diagram-controls output { font-variant-numeric:tabular-nums; }
.ds-research-diagram [hidden] { display:none!important; }
.ds-diagram-play:focus-visible,.ds-diagram-controls input:focus-visible { outline:2px solid var(--accent); outline-offset:4px; }
@media(max-width:760px) {
 .ds-research-feature { padding-block:32px 40px; }
 .ds-research-feature__text > p { margin:0 0 24px; }
 .ds-research-diagram { padding:20px 0; --sc-w:.6px; --sc-w-fine:.45px; --mk:2.1; }
 .ds-diagram-art { margin:0 0 24px; }
 /* On phones the scene uses the page gutters too; every callout stays inside the viewBox. */
 .ds-research-scene-svg { width:calc(100% + 2 * var(--gutter) - 4px); max-width:none; margin-inline:calc(2px - var(--gutter)); overflow:hidden; }
 .ds-scene-steps { grid-template-columns:1fr; gap:0; margin-top:16px; }
 .ds-explain-step { padding-block:14px; }
 .ds-explain-step h4 { font-size:21px; margin-bottom:6px; }
 .ds-explain-step p { max-width:none; font-size:14px; }
 .ds-diagram-controls { grid-template-columns:minmax(0,1fr) auto; gap:0 12px; font-size:13px; }
 .ds-diagram-controls label { grid-column:1/-1; }
 .ds-diagram-controls input { min-width:0; }
 .ds-diagram-controls output { max-width:170px; }
 .ds-research-feature__sources { gap:4px 24px; }
 .ds-research-feature__sources > span { width:100%; }
}
@media(prefers-reduced-motion:reduce) { .ds-research-diagram * { animation:none!important; transition:none!important; } }
@media print {
 .ds-diagram-play,.ds-diagram-controls { display:none!important; } .ds-research-diagram { break-inside:avoid; }
 :root[data-theme] .ds-research-diagram { --sc-w0:#fff; --sc-w1:#f3f5f6; --sc-w2:#e8ecee; --sc-w3:#dce2e5; --sc-w4:#cfd7db; --sc-s0:#eef3f5; --sc-s1:#e2eaee; --sc-s2:#d5e0e5; --sc-s3:#c7d5dc; --sc-s4:#b9cad3; --sc-b0:#f7efdc; --sc-b1:#eedfbd; --sc-b2:#e2cc9d; --sc-b3:#d4b77f; --sc-b4:#c3a164; --sc-k0:#3a3a3a; --sc-k1:#303030; --sc-k2:#282828; --sc-k3:#222; --sc-k4:#1c1c1c; --sc-edge:#444; --sc-edge-b:#8a6a30; --sc-edge-k:#111; --sc-fine:#8a8a8a; --sc-grid:#e2e2e2; --sc-ink:#000; --sc-accent:#222; --sc-soft:#ccc; --sc-glow:#555; --sc-warm:#8a6a30; --sc-ok:#333; --sc-wait:#777; --sc-screen:#2a2a2a; --sc-screen-ink:#bbb; --sc-screen-hi:#eee; --sc-shadow:#000; --sc-bg:#fff; }
}

/* The public topics remain reachable from Home in all retained appearances. */
